    } else if (FileUtils.fileExists(TERMUX_PREFIX_DIR_PATH, false)) {
        Logger.logInfo(LOG_TAG, "The termux prefix directory \"" + TERMUX_PREFIX_DIR_PATH + "\" does not exist but another file exists at its destination.");
