            errmsg = PackageUtils.setComponentState(context,TermuxConstants.TERMUX_PACKAGE_NAME,
                TERMUX_APP.FILE_SHARE_RECEIVER_ACTIVITY_CLASS_NAME,
                state, null, false, false);
            if (errmsg != null)
